# -*- coding: utf-8 -*-
"""Vietnamese answer explanations for every original N2-MOCK-13 item."""
from __future__ import annotations

VI_EXPLANATIONS = {
    "N2_13_M1_01": "根拠（こんきょ） nghĩa là căn cứ hoặc bằng chứng hỗ trợ một nhận định. Trong câu, đó là thông tin làm cơ sở cho kết luận của bài luận.",
    "N2_13_M1_02": "携わる（たずさわる） nghĩa là tham gia hoặc đảm nhiệm một công việc, hoạt động. Ở đây, giáo viên đã có thời gian tham gia biên soạn tài liệu.",
    "N2_13_M1_03": "普及（ふきゅう） là việc một công nghệ hoặc phương pháp được sử dụng rộng rãi. Cách đọc đúng là ふきゅう.",
    "N2_13_M1_04": "促す（うながす） nghĩa là khuyến khích hoặc thúc đẩy người khác hành động. Giáo viên khuyến khích sinh viên tự đặt câu hỏi.",
    "N2_13_M1_05": "省略（しょうりゃく） là lược bỏ một phần để nội dung ngắn gọn hơn. Ở đây, người nói rút bớt phần giải thích vì thời gian trình bày có hạn.",
    "N2_13_M2_01": "紹介（しょうかい） là giới thiệu hoặc chia sẻ thông tin về một người, sự vật hay hoạt động. Trong câu, người nói giới thiệu khóa học cho bạn.",
    "N2_13_M2_02": "照合（しょうごう） là đối chiếu nhiều thông tin để kiểm tra xem chúng có khớp nhau không. Câu nói về việc so sánh các tài liệu.",
    "N2_13_M2_03": "設置（せっち） nghĩa là lắp đặt hoặc bố trí thiết bị tại một địa điểm. Thiết bị được đặt sẵn trong từng phòng học.",
    "N2_13_M2_04": "再現（さいげん） là tạo lại cùng một kết quả trong cùng điều kiện. Nhóm nghiên cứu đang kiểm tra xem thí nghiệm có thể lặp lại hay không.",
    "N2_13_M2_05": "主体的（しゅたいてき） mô tả việc tự mình chủ động hành động. Câu nhấn mạnh sinh viên cần tích cực tham gia bằng ý chí của mình.",
    "N2_13_M3_01": "一元化 là tập trung nhiều nguồn vào một đầu mối; ở đây là tìm tài liệu trên nhiều máy chủ qua một ô tìm kiếm. 電子化 là số hóa, 標準化 là chuẩn hóa, còn 分散化 là phân tán nên không diễn tả việc gom về một đầu mối.",
    "N2_13_M3_02": "分類 là xếp các nội dung vào nhóm theo đặc điểm chung. Bài yêu cầu chia lỗi bài làm theo ba nguyên nhân để chọn cách hỗ trợ phù hợp.",
    "N2_13_M3_03": "促進 là thúc đẩy một quá trình tiến triển. Phụ đề giúp người học nắm nghĩa thuật ngữ và làm cho việc học tiến triển thuận lợi hơn.",
    "N2_13_M3_04": "照合 là đặt hai nguồn cạnh nhau để kiểm tra chúng có khớp không. So sánh tài liệu với nguyên bản giúp phát hiện lỗi chép số liệu hoặc tên riêng.",
    "N2_13_M3_05": "誤訳 là lỗi dịch làm sai ý của nguyên bản. Câu mô tả việc hiểu nhầm chủ ý rồi truyền đạt thành một nghĩa khác; 意訳, 直訳 và 和訳 tự chúng không có nghĩa là dịch sai.",
    "N2_13_M4_01": "考慮する nghĩa là cân nhắc và tính một yếu tố vào quyết định. Tuổi và chuyên ngành được đưa vào khi phân tích kết quả.",
    "N2_13_M4_02": "反映する nghĩa là thể hiện nội dung hoặc trạng thái ở một thứ khác. Ban biên tập kiểm tra xem tiêu đề có phản ánh đúng bài viết không.",
    "N2_13_M4_03": "見送る ở đây nghĩa là tạm hoãn hoặc chưa thực hiện kế hoạch. Bài nghiên cứu chưa được công bố sau khi phát hiện lỗi.",
    "N2_13_M4_04": "確認する là kiểm tra để biết nội dung có chính xác hay không. Câu khuyên đọc kỹ quy định và cách xử lý dữ liệu cá nhân.",
    "N2_13_M4_05": "損なう nghĩa là làm tổn hại hoặc làm mất đi giá trị, trạng thái vốn có. Cắt rời phát ngôn có thể khiến ý định của người nói bị sai lệch.",
    "N2_13_M4_06": "検討する là xem xét kỹ nhiều khả năng hoặc phương án. Giáo sư yêu cầu sinh viên cân nhắc một cách giải thích khác.",
    "N2_13_M4_07": "配慮 là quan tâm đến hoàn cảnh của người khác khi thiết kế hay hành động. Trang học được làm dễ dùng cho sinh viên mới.",
    "N2_13_M5_01": "明記する nghĩa là viết rõ ràng để người đọc có thể xác nhận. Ghi cụ thể các bước giúp người khác kiểm chứng cách làm.",
    "N2_13_M5_02": "踏まえて nghĩa là dựa trên hoặc cân nhắc thông tin đã có. Kế hoạch bài giảng được sửa sau khi tính đến ý kiến sinh viên.",
    "N2_13_M5_03": "訂正 là sửa nội dung sai thành nội dung đúng. Người quản lý chỉnh lại bài đăng trước khi thông tin sai lan rộng.",
    "N2_13_M5_04": "把握する là nắm được nội dung tổng thể hoặc các điểm chính. Người học cần hiểu trọng tâm bài giảng trước khi tổng hợp câu hỏi.",
    "N2_13_M5_05": "改善 là sửa vấn đề để tình trạng trở nên tốt hơn. Màn hình tìm kiếm được điều chỉnh để dễ sử dụng hơn.",
    "N2_13_M6_01": "慎重に確認する nghĩa là kiểm tra cẩn thận để tránh sai sót hoặc rủi ro. Tài liệu được rà soát trước khi công bố để không lộ thông tin cá nhân.",
    "N2_13_M6_02": "見込む trong câu này là dự đoán điều sẽ xảy ra. Người tổ chức dự tính số người tham gia tăng nên đặt phòng rộng hơn.",
    "N2_13_M6_03": "～に応じて nghĩa là điều chỉnh cách xử lý theo một điều kiện hoặc mức độ. Lượng tài liệu được thay đổi theo mức độ hiểu bài của sinh viên.",
    "N2_13_M6_04": "補う là thêm phần còn thiếu để nội dung đầy đủ hơn. Phần giải thích bằng chữ bổ sung thông tin khó truyền đạt qua biểu đồ.",
    "N2_13_M6_05": "省く nghĩa là bỏ đi phần không cần thiết. Báo cáo được rút gọn bằng cách xóa phần giải thích bị lặp.",
    "N2_13_M7_01": "わけにはいかない diễn tả việc không thể làm vì lý do đạo đức hoặc trách nhiệm. Không thể công bố kết quả nghiên cứu mà không ghi nguồn.",
    "N2_13_M7_02": "ばかりに diễn tả nguyên nhân dẫn đến kết quả không mong muốn. Vì không hỏi ý kiến người dùng nên nhiều người lúng túng khi thao tác.",
    "N2_13_M7_03": "ことによって nêu phương tiện hoặc nguyên nhân tạo ra kết quả. Nhờ ghi hình và công bố bài giảng, sinh viên vắng mặt có thể xem lại.",
    "N2_13_M7_04": "にしたがって diễn tả hai thay đổi xảy ra tương ứng. Khi bối cảnh được trình bày khác đi, cách người đọc hiểu tài liệu cũng thay đổi.",
    "N2_13_M7_05": "～からといって phủ định việc kết luận chỉ dựa trên một lý do. Mẫu khảo sát nhỏ không có nghĩa là kết quả hoàn toàn vô giá trị.",
    "N2_13_M7_06": "にあたって nghĩa là khi bắt đầu thực hiện một việc quan trọng. Cách ẩn danh dữ liệu cần được quyết định trước lúc chia sẻ.",
    "N2_13_M7_07": "だけあって đánh giá kết quả là xứng đáng với nguyên nhân nêu trước. Từ điển được chuyên gia kiểm duyệt nên phần giải nghĩa khá chi tiết.",
    "N2_13_M7_08": "ばかりに nêu nguyên nhân gây ra một bất lợi. Vì đăng ký mà không đọc quy định, người dùng mới biết sau đó rằng không thể đổi phạm vi công khai dữ liệu.",
    "N2_13_M7_09": "ために diễn tả mục đích. Biểu mẫu ẩn danh được tạo ra nhằm giúp sinh viên dễ đặt câu hỏi hơn.",
    "N2_13_M7_10": "からといって～とは限らない nghĩa là không thể khẳng định chỉ vì lý do đó. Thứ hạng tìm kiếm cao không bảo đảm thông tin đáng tin.",
    "N2_13_M7_11": "ものだ trong ngữ cảnh này hồi tưởng một thói quen trong quá khứ. Cụm “khi tôi học năm nhất” cho biết thời điểm giáo viên thường chờ sinh viên tự suy nghĩ.",
    "N2_13_M7_12": "と nối một điều kiện với kết quả thường xảy ra. Nếu nộp nguyên bản dịch, có thể vẫn còn cách diễn đạt không hợp ngữ cảnh.",
    "N2_13_M8_01": "Câu hoàn chỉnh nói rằng nhà nghiên cứu nêu rõ nguồn số liệu để người đọc kiểm tra kết quả. Cụm 明示することによって chỉ phương tiện, rồi nối tự nhiên với phần kết quả phía sau.",
    "N2_13_M8_02": "Câu hoàn chỉnh là “cần điều chỉnh thứ tự giải thích theo mức độ hiểu bài của sinh viên”. に合わせて nêu tiêu chí điều chỉnh, sau đó tân ngữ 説明の順序を được nối với động từ.",
    "N2_13_M8_03": "Ý câu là không chỉ dựa vào tiêu đề mà còn kiểm tra nội dung bài và nguồn trích dẫn. Cụm 本文と出典も đứng trước phần khuyên nên xác nhận.",
    "N2_13_M8_04": "Câu nói cần kiểm tra trước khi thêm chức năng mới xem gánh nặng cho người dùng có tăng không. Mệnh đề chứa 増えないか diễn tả điều cần xác nhận.",
    "N2_13_M8_05": "Câu hoàn chỉnh yêu cầu đối chiếu nhiều tài liệu trước rồi mới công bố nội dung bài viết. Cụm 複数の資料を照合したうえで nêu việc cần hoàn tất trước hành động sau.",
    "N2_13_M9_01": "一方で dùng để đối chiếu hai mặt khác nhau. Đoạn văn nêu lợi ích của video ghi hình rồi chuyển sang lo ngại về mức độ tham gia trên lớp.",
    "N2_13_M9_02": "からといって～ということではない phủ định kết luận vội vàng. Việc xem video giúp hiểu bài không có nghĩa là không cần đặt câu hỏi hay thảo luận.",
    "N2_13_M9_03": "とともに ở đây diễn tả hai việc được làm song song. Người học dùng video như tài liệu bổ trợ và hỏi lại những điểm chưa rõ.",
    "N2_13_M9_04": "だけでなく bổ sung thêm một tiêu chí đánh giá. Ngoài số lượt sử dụng, cần xem cả phần tự đánh giá của sinh viên.",
    "N2_13_M9_05": "ことにしている diễn tả một phương châm được duy trì. Trung tâm sẽ điều chỉnh hình thức hỗ trợ dựa trên kết quả cuối học kỳ.",
    "N2_13_M10_01": "Bảng tin cho phép đăng câu hỏi ẩn danh nhưng giáo viên chỉ trả lời hai lần mỗi tuần, nên không phải lúc nào cũng có phản hồi ngay. Vấn đề điểm số hay thông tin cá nhân cần gửi đến bộ phận phụ trách.",
    "N2_13_M10_02": "Khảo sát nhằm tìm hiểu tình hình sử dụng sách điện tử để quyết định số lượng gia hạn cho năm sau. Trả lời là tự nguyện và khảo sát không thu thập thông tin cá nhân.",
    "N2_13_M10_03": "Người báo lỗi cần ghi cả vị trí sai và cách viết đúng. Bộ phận phụ trách xác nhận trước khi sửa; nếu chưa thể sửa ngay, trang sẽ hiển thị ngày dự kiến.",
    "N2_13_M10_04": "Hệ thống chỉ lưu tiêu đề, ngày và bản tóm tắt để so sánh trong lớp. Muốn đọc toàn văn phải dùng cơ sở dữ liệu có giấy phép; không được tải ra ngoài.",
    "N2_13_M10_05": "Người dùng có thể đổi ngày, giờ nhận thông báo hoặc tắt thông báo. Không có chức năng tăng thông báo trước kỳ thi và lịch sử chỉ được lưu 30 ngày.",
    "N2_13_M11_01": "Video của sinh viên là tài liệu nhập môn, không thay thế phần giảng của giáo viên. Vì chạy đua lượt xem có thể làm nội dung thiên về trình diễn, việc đánh giá tập trung vào tính chính xác và mạch giải thích.",
    "N2_13_M11_02": "Trường đã thêm tiêu đề chương và liên kết để tìm video dễ hơn, nhưng giữ nguyên thời hạn xem nhằm hạn chế đề thi bị phát tán ra ngoài.",
    "N2_13_M11_03": "Ban biên tập muốn phân biệt rõ điều đã xác minh với điều chưa xác minh. Nhờ vậy, độc giả có thể tự đánh giá độ tin cậy của thông tin.",
    "N2_13_M11_04": "Phụ đề tự động hữu ích nhưng có thể nhận dạng sai thuật ngữ và tên riêng. Giáo viên khuyên kiểm tra điểm quan trọng bằng bản ghi âm hoặc tài liệu; việc sửa ngay trong ngày không được bảo đảm.",
    "N2_13_M11_05": "Thi đua về thời gian nhập liệu có thể khiến sinh viên ưu tiên số ghi nhận hơn việc hiểu bài. Vì vậy, khoa thử cách viết phản hồi hằng tuần về điều đã làm được và cách học tiếp theo.",
    "N2_13_M11_06": "Phòng nghiên cứu dùng từ dễ hiểu nhưng vẫn nêu phạm vi nghiên cứu và giới hạn cần kiểm chứng. Mục tiêu là vừa dễ đọc vừa chính xác.",
    "N2_13_M11_07": "Đơn đăng ký không thể sửa sau khi gửi thường bị đính kèm nhầm tài liệu. Biểu mẫu mới nhắc kiểm tra các điểm chính lúc bắt đầu và trước khi gửi, đồng thời nêu cách xử lý nếu lỡ gửi sai.",
    "N2_13_M11_08": "Khi tăng số lượng góp ý, nhiều nhận xét trở nên ngắn và thiếu căn cứ. Nhóm biên tập chuyển sang coi trọng lý do, cách kiểm tra và quá trình đọc lại.",
    "N2_13_M11_09": "Một số sinh viên không phù hợp với hình thức trực tuyến nên trường vẫn giữ lựa chọn gọi điện và đặt lịch gặp trực tiếp. Hiệu quả được đánh giá qua cả số lượt dùng lẫn phản hồi ẩn danh.",
    "N2_13_M12_01": "A quy định thời hạn lưu và người được xem tài liệu; B muốn kéo dài thời hạn và cho phép xem sau khi tốt nghiệp. Cả hai cùng bàn về thời gian lưu và đối tượng có quyền truy cập.",
    "N2_13_M12_02": "A đã ấn định thời hạn một năm cùng điều kiện gia hạn. B muốn lấy ý kiến các bên trước khi quyết định, chứ chưa kết luận rằng mọi tài liệu phải công khai vô thời hạn.",
    "N2_13_M13_01": "Nhóm truyền thông trước tiên hỏi nội dung nào cần được hiểu và ai là người nghe, rồi chọn một thông điệp trọng tâm. Mục tiêu không phải tăng lượt xem hay xóa hết thuật ngữ.",
    "N2_13_M13_02": "Sinh viên ngoài chuyên ngành chỉ ra chỗ khó hiểu khi đọc lần đầu. Nhóm dùng phản hồi đó để kiểm tra liệu người nghe phổ thông có theo kịp hay không.",
    "N2_13_M13_03": "Tác giả không chủ trương chỉ rút ngắn thông tin; cần nêu rõ kết quả chính và phạm vi áp dụng, đồng thời chỉ đường đến căn cứ chi tiết.",
    "N2_13_M14_01": "Buổi góp ý trang trình chiếu diễn ra thứ Tư, từ 12:20 đến 12:50, tại phòng hỗ trợ học tập ở tầng hai tòa nhà chính.",
    "N2_13_M14_02": "Buổi tư vấn trích dẫn và bản quyền diễn ra trực tuyến vào thứ Năm. Cần đăng ký trước trên trang tư vấn của cổng trường muộn nhất 10 phút trước giờ bắt đầu.",
    "N2_13_M1_L01": "Giảng viên yêu cầu không phát tài liệu khi chưa xác nhận nguồn biểu đồ. Sinh viên sẽ tìm báo cáo khảo sát gốc trước; nếu không tìm được thì hỏi lại giảng viên.",
    "N2_13_M1_L02": "Đặt trước có thể phải chờ, nên người đàn ông chọn phương án nhanh hơn là tìm cuốn sách giấy ở thư viện cơ sở phụ.",
    "N2_13_M1_L03": "Sau khi tính lại, họ chưa rõ bảng có tính câu trả lời của người vắng mặt không. Họ thống nhất đối chiếu danh sách câu trả lời với bảng tổng hợp trước khi gửi.",
    "N2_13_M1_L04": "Bản ghi hình đã sửa chỉ có vào ngày mai, còn tài liệu bài giảng có thể dùng ngay. Sinh viên sẽ làm bài bằng tài liệu và ghi lại điểm chưa hiểu.",
    "N2_13_M1_L05": "Đối tượng được dự buổi giới thiệu chưa rõ, nên nữ sinh sẽ hỏi phòng nghiên cứu qua email trước khi công bố thông báo.",
    "N2_13_M2_L01": "Bài phải nộp dưới dạng PDF trước 17 giờ thứ Sáu. Không thể ghi đè sau khi nộp, nhưng có thể rút lại và nộp bản mới trước hạn.",
    "N2_13_M2_L02": "Không cần đăng ký nhưng số máy tính có hạn. Người muốn làm thực hành phải đến đúng giờ bắt đầu; người đến muộn chỉ được dự thính.",
    "N2_13_M2_L03": "Bản dịch tự động có thể sai thuật ngữ và câu phủ định. Người học cần kiểm tra phần trích dẫn với nguyên bản và tự xác nhận nghĩa của bản dịch.",
    "N2_13_M2_L04": "Dù viết lại cho dễ đọc, không được bỏ đối tượng khảo sát hay thời gian khảo sát vì người đọc cần chúng để hiểu phạm vi kết quả.",
    "N2_13_M2_L05": "Tệp có tên hoặc thông tin liên lạc phải được lưu ở nơi chỉ người được phép mới có thể truy cập.",
    "N2_13_M2_L06": "Tư vấn khẩn cấp không nhận qua biểu mẫu đặt lịch; sinh viên cần gọi điện trong giờ tiếp nhận.",
    "N2_13_M3_L01": "Giảng viên sẽ thu câu hỏi trên trang lớp, gom những thắc mắc chung rồi giải thích trong buổi học kế tiếp, thay vì trả lời riêng từng câu.",
    "N2_13_M3_L02": "Kết quả tìm kiếm chỉ là gợi ý. Cần kiểm tra ngày đăng, mục đích, nguồn trích dẫn và so sánh với tài liệu khác.",
    "N2_13_M3_L03": "Số thông báo không quyết định việc học có tiếp tục hay không; việc tự chọn mục tiêu và thời gian có liên quan hơn. Sinh viên sẽ thử chức năng tự chọn cách cài đặt thông báo.",
    "N2_13_M3_L04": "Bản tóm tắt AI có thể thêm nhận định không có trong bài gốc. Người nghiên cứu dùng nó làm công cụ hỗ trợ nhưng kiểm tra các luận điểm quan trọng trong bài luận ban đầu.",
    "N2_13_M3_L05": "Chỉ đăng thêm tài liệu chưa giải quyết được vấn đề không biết bắt đầu từ đâu. Người phụ trách sẽ chỉ rõ thứ tự xem tài liệu cơ bản rồi đến tài liệu mở rộng.",
    "N2_13_M4_L01": "Người hỏi hỏi rõ phải mở màn hình nào để xem hạn nghe nhìn bản ghi. Câu trả lời chỉ đúng địa điểm cụ thể: mục “録画” trên trang từng môn; hai lựa chọn còn lại chỉ nói về thời hạn, không nói nơi tra cứu.",
    "N2_13_M4_L02": "Vì thời hạn đăng ký đã qua, cách phù hợp là hỏi bộ phận phụ trách xem họ còn nhận hồ sơ hay không.",
    "N2_13_M4_L03": "Người hỏi muốn xem điểm kỳ trước. Hướng dẫn chọn học kỳ trong mục điểm số trả lời trực tiếp câu hỏi.",
    "N2_13_M4_L04": "Người hỏi cần biết nơi báo lỗi phụ đề, nên hướng dẫn chọn nút “Báo lỗi” ngay dưới video là phù hợp.",
    "N2_13_M4_L05": "Khi trang web không có số trang, có thể dùng ngày đăng hoặc tiêu đề theo quy định trích dẫn để định vị nguồn.",
    "N2_13_M4_L06": "Muốn làm thực hành trên máy tính phải có mặt từ đầu giờ; người đến giữa buổi chỉ được quan sát.",
    "N2_13_M4_L07": "Người dùng muốn đổi giờ thông báo, nên hướng dẫn vào phần cài đặt để chỉnh ngày trong tuần và thời gian là phù hợp.",
    "N2_13_M4_L08": "Nếu còn trước hạn, người nộp có thể rút tệp sai rồi nộp lại tệp đúng.",
    "N2_13_M4_L09": "Câu hỏi là có cần mô tả chi tiết nội dung tư vấn không. Câu trả lời cho biết không cần, chỉ chọn giờ và hình thức gặp.",
    "N2_13_M4_L10": "Tệp chứa tên sinh viên không nên để ở thư mục chia sẻ chung; cần chuyển sang nơi giới hạn người xem.",
    "N2_13_M4_L11": "Người hỏi cần biết tầng của địa điểm. Câu trả lời nêu tầng hai tòa nhà chính và vị trí quầy tiếp tân.",
    "N2_13_M5_L01": "Để tránh hiểu sai do số người trả lời khác nhau, cần nêu tỷ lệ và số người chưa trả lời. Ý kiến tự do phải được ẩn danh và tổng hợp theo xu hướng.",
    "N2_13_M5_L02": "Không thể tin ảnh chỉ vì bài đăng có ảnh; cần xác minh nguồn và thời điểm. Nếu chưa xác minh được thì không khẳng định đó là sự thật, mà dùng làm bài tập về cách kiểm chứng.",
    "N2_13_M5_L03": "Nhóm sẽ xem ngoài số người dùng còn có tình huống nào được hỗ trợ và vấn đề có được giải quyết hay không, đồng thời giữ dữ liệu ở dạng không nhận diện cá nhân.",
}


def apply_vietnamese_explanations(items: list[dict]) -> list[dict]:
    for item in items:
        explanation = VI_EXPLANATIONS.get(item.get("id"))
        if not explanation:
            raise ValueError(f"Missing Vietnamese explanation: {item.get('id')}")
        item["explanationVi"] = explanation
        answer_id = item.get("correctAnswer")
        item["distractorExplanations"] = {
            option["id"]: f"Phương án «{option['text']}» không phù hợp với dữ kiện hoặc cấu trúc của câu. {explanation}"
            for option in item.get("options", []) if option.get("id") != answer_id
        }
    return items
